const express = require('express');
const Database = require('better-sqlite3');
const fs = require('fs');
const path = require('path');

const PORT = Number(process.env.PORT || 3000);
const HOST = '0.0.0.0';
const DB_PATH = path.join(__dirname, 'patchpad.db');
const SEED_PATH = '/assets/incident_seed.json';
const PUBLIC_DIR = path.join(__dirname, 'public');

function readSeedDocument() {
  const seed = JSON.parse(fs.readFileSync(SEED_PATH, 'utf8'));
  if (!seed || !seed.document) {
    throw new Error('Seed document is missing the document payload.');
  }
  return seed.document;
}

function buildSeedContent(document) {
  const lines = [];

  if (document.title) lines.push(`Title: ${document.title}`);
  if (document.author) lines.push(`Author: ${document.author}`);
  if (document.summary) lines.push(`Summary: ${document.summary}`);
  lines.push('');

  for (const section of document.sections || []) {
    lines.push(section);
  }

  const generatedCount = Number(document.generatedLineCount || 0);
  const width = Number(document.generatedLineNumberWidth || 1);
  const template = String(document.generatedLineTemplate || 'Log line {n}');
  for (let i = 1; i <= generatedCount; i += 1) {
    const number = String(i).padStart(width, '0');
    lines.push(template.replace(/\{n\}/g, number));
  }

  for (const tail of document.tailSections || []) {
    lines.push(tail);
  }

  return lines.join('\n');
}

function createDatabase() {
  const db = new Database(DB_PATH);
  db.pragma('foreign_keys = ON');
  db.pragma('journal_mode = WAL');

  db.exec(`
    CREATE TABLE IF NOT EXISTS reports (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      author TEXT NOT NULL,
      summary TEXT NOT NULL,
      current_content TEXT NOT NULL,
      current_revision INTEGER NOT NULL,
      created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
      updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP)
    );

    CREATE TABLE IF NOT EXISTS revisions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE,
      revision_number INTEGER NOT NULL,
      content TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
      UNIQUE(report_id, revision_number)
    );

    CREATE INDEX IF NOT EXISTS idx_revisions_report_revision
      ON revisions(report_id, revision_number DESC);
  `);

  return db;
}

const db = createDatabase();
const seedDocument = readSeedDocument();
const seedContent = buildSeedContent(seedDocument);

const insertSeed = db.transaction(() => {
  const reportCount = db.prepare('SELECT COUNT(*) AS count FROM reports').get().count;
  if (reportCount > 0) {
    return;
  }

  db.prepare(
    `INSERT INTO reports (id, title, author, summary, current_content, current_revision, created_at, updated_at)
     VALUES (@id, @title, @author, @summary, @content, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)`
  ).run({
    id: seedDocument.id,
    title: seedDocument.title,
    author: seedDocument.author,
    summary: seedDocument.summary,
    content: seedContent,
  });

  db.prepare(
    `INSERT INTO revisions (report_id, revision_number, content, created_at)
     VALUES (?, 1, ?, CURRENT_TIMESTAMP)`
  ).run(seedDocument.id, seedContent);
});

insertSeed();

const app = express();
app.disable('x-powered-by');
app.use(express.json({ limit: '2mb', type: ['application/json', 'application/*+json'] }));
app.use(express.static(PUBLIC_DIR, { extensions: ['html'] }));

const statements = {
  listReports: db.prepare('SELECT id, title, author, current_revision AS currentRevision, updated_at AS updatedAt FROM reports ORDER BY title COLLATE NOCASE, id'),
  getReport: db.prepare('SELECT id, title, author, summary, current_content AS currentContent, current_revision AS currentRevision, created_at AS createdAt, updated_at AS updatedAt FROM reports WHERE id = ?'),
  getRevisions: db.prepare('SELECT revision_number AS revisionNumber, created_at AS createdAt FROM revisions WHERE report_id = ? ORDER BY revision_number DESC'),
  getRevision: db.prepare('SELECT revision_number AS revisionNumber, content, created_at AS createdAt FROM revisions WHERE report_id = ? AND revision_number = ?'),
};

function getReportOr404(reportId, res) {
  const report = statements.getReport.get(reportId);
  if (!report) {
    res.status(404).json({ error: 'Report not found.' });
    return null;
  }
  return report;
}

function formatReport(report) {
  return {
    id: report.id,
    title: report.title,
    author: report.author,
    summary: report.summary,
    content: report.currentContent,
    currentRevision: report.currentRevision,
    createdAt: report.createdAt,
    updatedAt: report.updatedAt,
    revisions: statements.getRevisions.all(report.id),
  };
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function bootstrapJson(value) {
  return JSON.stringify(value).replace(/</g, '\\u003c');
}

app.get('/', (req, res) => {
  const reports = statements.listReports.all();
  const currentId = reports[0] ? reports[0].id : null;
  const bootstrap = bootstrapJson({
    reports,
    currentId,
  });

  res.type('html').send(`<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>PatchPad</title>
    <link rel="stylesheet" href="/styles.css" />
    <script>
      window.__PATCHPAD_BOOTSTRAP__ = ${bootstrap};
    </script>
  </head>
  <body>
    <div id="app-shell">
      <noscript>
        <div class="noscript">PatchPad requires JavaScript to edit reports.</div>
      </noscript>
      <div id="app"></div>
    </div>
    <script src="/app.js" defer></script>
  </body>
</html>`);
});

app.get('/api/reports', (req, res) => {
  res.json({ reports: statements.listReports.all() });
});

app.get('/api/reports/:reportId', (req, res) => {
  const report = getReportOr404(req.params.reportId, res);
  if (!report) return;
  res.json(formatReport(report));
});

app.get('/api/reports/:reportId/revisions', (req, res) => {
  const report = getReportOr404(req.params.reportId, res);
  if (!report) return;
  res.json({
    reportId: report.id,
    revisions: statements.getRevisions.all(report.id),
  });
});

app.get('/api/reports/:reportId/revisions/:revisionNumber', (req, res) => {
  const report = getReportOr404(req.params.reportId, res);
  if (!report) return;

  const revisionNumber = Number(req.params.revisionNumber);
  if (!Number.isInteger(revisionNumber) || revisionNumber < 1) {
    res.status(400).json({ error: 'Revision number must be a positive integer.' });
    return;
  }

  const revision = statements.getRevision.get(report.id, revisionNumber);
  if (!revision) {
    res.status(404).json({ error: 'Revision not found.' });
    return;
  }

  res.json({
    reportId: report.id,
    revisionNumber: revision.revisionNumber,
    createdAt: revision.createdAt,
    content: revision.content,
  });
});

app.post('/api/reports/:reportId/save', (req, res) => {
  const report = getReportOr404(req.params.reportId, res);
  if (!report) return;

  const { documentId, baseRevision, content } = req.body || {};
  if (documentId != null && documentId !== report.id) {
    res.status(400).json({ error: 'documentId does not match the target report.' });
    return;
  }

  if (!Number.isInteger(baseRevision)) {
    res.status(400).json({ error: 'baseRevision must be an integer.' });
    return;
  }

  if (typeof content !== 'string') {
    res.status(400).json({ error: 'content must be text.' });
    return;
  }

  if (baseRevision !== report.currentRevision) {
    res.status(409).json({
      error: 'Save rejected because the report has changed since editing started.',
      currentRevision: report.currentRevision,
      currentContent: report.currentContent,
      updatedAt: report.updatedAt,
    });
    return;
  }

  if (content === report.currentContent) {
    res.json({
      ok: true,
      saved: false,
      revision: report.currentRevision,
      updatedAt: report.updatedAt,
    });
    return;
  }

  const nextRevision = report.currentRevision + 1;
  const now = new Date().toISOString();
  const saveTransaction = db.transaction(() => {
    db.prepare(
      `INSERT INTO revisions (report_id, revision_number, content, created_at)
       VALUES (?, ?, ?, CURRENT_TIMESTAMP)`
    ).run(report.id, nextRevision, content);

    db.prepare(
      `UPDATE reports
       SET current_content = ?, current_revision = ?, updated_at = CURRENT_TIMESTAMP
       WHERE id = ?`
    ).run(content, nextRevision, report.id);
  });

  saveTransaction();

  res.json({
    ok: true,
    saved: true,
    revision: nextRevision,
    updatedAt: now,
  });
});

app.use((req, res) => {
  res.status(404).json({ error: 'Not found.' });
});

app.use((err, req, res, next) => {
  if (err instanceof SyntaxError && 'body' in err) {
    res.status(400).json({ error: 'Malformed JSON request body.' });
    return;
  }

  console.error(err);
  res.status(500).json({ error: 'Unexpected server error.' });
});

app.listen(PORT, HOST, () => {
  console.log(`PatchPad listening on http://${HOST}:${PORT}`);
  console.log(`SQLite path: ${DB_PATH}`);
});

* {
  box-sizing: border-box;
}

:root {
  color-scheme: dark;
  --bg: #0f172a;
  --panel: #111827;
  --panel-soft: #1f2937;
  --panel-muted: #273244;
  --line: #334155;
  --text: #e5eefc;
  --muted: #94a3b8;
  --accent: #60a5fa;
  --accent-strong: #2563eb;
  --success: #34d399;
  --warning: #f59e0b;
  --danger: #f87171;
  --selection: rgba(96, 165, 250, 0.28);
  --selection-strong: rgba(37, 99, 235, 0.45);
  --shadow: 0 16px 40px rgba(0, 0, 0, 0.28);
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, Monaco, 'Liberation Mono', monospace;
  --sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

html,
body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at top, #1e293b 0, var(--bg) 50%);
  color: var(--text);
  font-family: var(--sans);
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  border: 1px solid var(--line);
  background: linear-gradient(180deg, #1f2937, #172033);
  color: var(--text);
  border-radius: 10px;
  padding: 0.55rem 0.85rem;
  cursor: pointer;
  transition: transform 120ms ease, border-color 120ms ease, background 120ms ease;
}

button:hover,
button:focus-visible,
input:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.16);
}

button:hover {
  transform: translateY(-1px);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

#app-shell,
#app {
  width: 100%;
  height: 100%;
}

.noscript {
  margin: 1rem;
  padding: 1rem 1.25rem;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: rgba(17, 24, 39, 0.9);
}

.layout {
  display: flex;
  width: 100%;
  height: 100%;
  min-width: 0;
}

.sidebar {
  width: 280px;
  min-width: 240px;
  border-right: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(15, 23, 42, 0.88);
  backdrop-filter: blur(12px);
  padding: 1rem;
  overflow: auto;
}

.sidebar h2,
.history-panel h2,
.editor-title {
  margin: 0;
}

.sidebar .section-label,
.history-panel .section-label,
.find-label {
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  font-size: 0.74rem;
  margin-bottom: 0.55rem;
}

.report-list,
.revision-list {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}

.report-card,
.revision-card,
.preview-card {
  border: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(15, 23, 42, 0.78);
  border-radius: 16px;
  box-shadow: var(--shadow);
}

.report-card {
  padding: 0.85rem;
}

.report-card.active {
  border-color: rgba(96, 165, 250, 0.48);
  box-shadow: 0 0 0 1px rgba(96, 165, 250, 0.2), var(--shadow);
}

.report-title {
  font-weight: 700;
  margin-bottom: 0.35rem;
}

.report-meta,
.revision-meta,
.status-line,
.cursor-line,
.find-status,
.help-line {
  color: var(--muted);
  font-size: 0.92rem;
}

.main {
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.header {
  padding: 1rem 1rem 0.9rem;
  border-bottom: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(15, 23, 42, 0.72);
  backdrop-filter: blur(12px);
}

.header-top {
  display: flex;
  gap: 1rem;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
}

.title-block {
  min-width: 0;
}

.editor-title {
  font-size: 1.5rem;
  line-height: 1.1;
  margin-bottom: 0.35rem;
}

.title-subtitle {
  color: var(--muted);
  line-height: 1.35;
}

.toolbar,
.findbar,
.statusbar {
  display: flex;
  gap: 0.6rem;
  flex-wrap: wrap;
  align-items: center;
}

.toolbar {
  justify-content: flex-end;
}

.findbar {
  margin-top: 0.9rem;
  padding-top: 0.75rem;
  border-top: 1px solid rgba(148, 163, 184, 0.14);
}

.find-group {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  flex-wrap: wrap;
}

.find-group input {
  min-width: 15rem;
  max-width: 100%;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: rgba(17, 24, 39, 0.95);
  color: var(--text);
  padding: 0.55rem 0.75rem;
}

.find-count {
  min-width: 8rem;
  text-align: right;
  color: var(--muted);
}

.find-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.statusbar {
  margin-top: 0.85rem;
  justify-content: space-between;
  gap: 0.75rem;
}

.message {
  color: var(--muted);
}

.message.info {
  color: #bfdbfe;
}

.message.success {
  color: var(--success);
}

.message.warning {
  color: #fbbf24;
}

.message.error {
  color: var(--danger);
}

.workspace {
  flex: 1;
  min-height: 0;
  min-width: 0;
  display: flex;
  gap: 0;
}

.editor-panel {
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 1rem;
}

.editor-shell {
  flex: 1;
  min-width: 0;
  min-height: 0;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 18px;
  background: rgba(15, 23, 42, 0.78);
  box-shadow: var(--shadow);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.editor-scroller {
  flex: 1;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  outline: none;
}

.document {
  min-width: 100%;
  width: max-content;
  padding: 0.7rem 0;
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1.55;
}

.line-row {
  display: grid;
  grid-template-columns: 5.25rem auto;
  align-items: start;
  min-height: 1.55em;
}

.line-row.active-line {
  background: rgba(37, 99, 235, 0.08);
}

.line-number {
  position: sticky;
  left: 0;
  z-index: 1;
  padding: 0 0.9rem 0 0.5rem;
  color: #7f92b3;
  text-align: right;
  user-select: none;
  background: linear-gradient(90deg, rgba(15, 23, 42, 0.98), rgba(15, 23, 42, 0.88));
  border-right: 1px solid rgba(148, 163, 184, 0.1);
}

.line-text {
  padding: 0 1rem 0 0.9rem;
  white-space: pre;
  color: var(--text);
  min-width: max-content;
}

.selection {
  background: var(--selection);
  border-radius: 3px;
}

.selection.active-selection {
  background: var(--selection-strong);
}

.caret {
  display: inline-block;
  width: 2px;
  height: 1.15em;
  margin: 0 -1px;
  vertical-align: -0.22em;
  background: #fb923c;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.18);
}

.side-panel {
  width: 360px;
  min-width: 320px;
  border-left: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(15, 23, 42, 0.92);
  backdrop-filter: blur(12px);
  padding: 1rem;
  overflow: auto;
}

.history-panel {
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
  min-height: 0;
}

.revision-card {
  padding: 0.85rem;
}

.revision-card.current {
  border-color: rgba(96, 165, 250, 0.45);
}

.revision-header {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: center;
  margin-bottom: 0.4rem;
}

.revision-number {
  font-weight: 700;
}

.revision-actions,
.preview-actions {
  display: flex;
  gap: 0.45rem;
  flex-wrap: wrap;
  margin-top: 0.6rem;
}

.preview-card {
  padding: 0.9rem;
}

.preview-content {
  max-height: 240px;
  overflow: auto;
  margin-top: 0.7rem;
  padding: 0.75rem;
  border-radius: 12px;
  background: rgba(2, 6, 23, 0.7);
  border: 1px solid rgba(148, 163, 184, 0.14);
  white-space: pre-wrap;
  word-break: break-word;
  font-family: var(--mono);
  line-height: 1.5;
}

.message-banner {
  display: flex;
  gap: 0.75rem;
  align-items: flex-start;
  justify-content: space-between;
  padding: 0.75rem 0.9rem;
  border-radius: 14px;
  border: 1px solid rgba(248, 113, 113, 0.35);
  background: rgba(127, 29, 29, 0.24);
  color: #fecaca;
}

.message-banner .banner-actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.hidden {
  display: none !important;
}

@media (max-width: 1200px) {
  .sidebar {
    width: 240px;
    min-width: 220px;
  }

  .side-panel {
    width: 300px;
    min-width: 280px;
  }
}

@media (max-width: 1024px) {
  body {
    overflow: auto;
  }

  .layout,
  .workspace {
    flex-direction: column;
    height: auto;
  }

  .sidebar,
  .side-panel {
    width: auto;
    min-width: 0;
    border: none;
    border-bottom: 1px solid rgba(148, 163, 184, 0.18);
  }

  .editor-panel {
    min-height: 60vh;
  }
}

(() => {
  const bootstrap = window.__PATCHPAD_BOOTSTRAP__ || { reports: [], currentId: null };
  const appRoot = document.getElementById('app');

  appRoot.innerHTML = `
    <div class="layout">
      <aside class="sidebar">
        <div class="section-label">Reports</div>
        <div id="reportList" class="report-list"></div>
      </aside>

      <div class="main">
